const tabId = 343605502;

const controls = await browserjs(tabId, () => {
  // Find all elements containing text "Increment", "Quantity", "Decrement", "Add to Cart"
  const elements = Array.from(document.querySelectorAll('button, input, div, span')).filter(el => {
    const t = el.innerText || el.getAttribute('aria-label') || '';
    return /increment|decrement|quantity|add to cart/i.test(t);
  }).map(el => ({
    tagName: el.tagName,
    className: el.className,
    id: el.id,
    name: el.getAttribute('name'),
    type: el.getAttribute('type'),
    value: el.value || el.getAttribute('value'),
    ariaLabel: el.getAttribute('aria-label'),
    text: el.innerText ? el.innerText.trim().slice(0, 50) : '',
    outerHTML: el.outerHTML.slice(0, 200)
  }));
  return elements;
});

console.log("Controls:", JSON.stringify(controls.slice(0, 15), null, 2));

const tabId = 343605502;

const mainProductControls = await browserjs(tabId, () => {
  // Let's find elements that contain "Quantity Input" or "Increment" or "Decrement"
  const allNodes = Array.from(document.querySelectorAll('*')).filter(el => {
    return el.children.length === 0 && /Increment|Decrement|Quantity Input/i.test(el.textContent);
  }).map(el => {
    const parent = el.parentElement;
    const grandparent = parent ? parent.parentElement : null;
    return {
      tag: el.tagName,
      text: el.textContent,
      parentHtml: parent ? parent.outerHTML.slice(0, 300) : null,
      grandparentHtml: grandparent ? grandparent.outerHTML.slice(0, 500) : null
    };
  });

  return allNodes;
});

console.log("Main product quantity nodes:", JSON.stringify(mainProductControls, null, 2));

